        print(">>", kw, "page", page_of(m.start()), "ctx:", full[m.start():m.start()+200].replace("\n"," ")[:200])
print()
# 生物质能发电 context
for m in list(re.finditer("生物质能发电", full))[:10]:
    print(">> 生物质能发电 page", page_of(m.start()), "ctx:", full[m.start():m.start()+150].replace("\n"," ")[:150])
